search=next(n for n in a2['nodes'] if n['name']=='Google Web');model=next(n for n in a3['nodes'] if n['type'].endswith('lmChatOllama'));parser=next(n for n in a3['nodes'] if n['type'].endswith('outputParserStructured'));chain=next(n for n in a3['nodes'] if n['type'].endswith('chainLlm'))
