nodes=[];connections={}
def add(name,typ,params,pos,version=1):
 n={'id':str(uuid.uuid4()),'name':name,'type':typ,'typeVersion':version,'parameters':params,'position':pos};nodes.append(n);return n
def link(a,b,output=0):
 ports=connections.setdefault(a,{}).setdefault('main',[])
 while len(ports)<=output:ports.append([])
 ports[output].append({'node':b,'type':'main','index':0})
def code(name,body,pos):return add(name,'n8n-nodes-base.code',{'jsCode':logic+'\n'+body},pos,2)
def google(name,pos):
 n=add(name,search['type'],{'operation':'google','q':'={{ $json.query }}','additionalFields':{'hl':'en'},'requestOptions':{}},pos,search['typeVersion']);n['credentials']=copy.deepcopy(search['credentials']);n.update(retryOnFail=True,maxTries=2,waitBetweenTries=2000,onError='continueRegularOutput')
def llm(name,prompt,schema,pos):
 n=add(name,chain['type'],{'promptType':'define','text':prompt,'hasOutputParser':True,'batching':{}},pos,chain['typeVersion']);n.update(onError='continueRegularOutput',retryOnFail=True,maxTries=2,waitBetweenTries=1000)
 m=copy.deepcopy(model);m.update(id=str(uuid.uuid4()),name=name+' - Gemma',position=[pos[0],pos[1]+240]);m['parameters']['options'].update(temperature=0,numCtx=16384,numPredict=4096);nodes.append(m)
 p=add(name+' - Schema',parser['type'],{'schemaType':'manual','inputSchema':json.dumps(schema)},[pos[0]+180,pos[1]+240],parser['typeVersion'])
 for obj,kind in [(m,'ai_languageModel'),(p,'ai_outputParser')]:connections[obj['name']]={kind:[ [{'node':name,'type':kind,'index':0}] ]}
def schema(fields,arrayname):return {'type':'object','properties':{arrayname:{'type':'array','items':{'type':'object','properties':{k:{'type':'string'} for k in fields},'required':fields,'additionalProperties':False}}},'required':[arrayname],'additionalProperties':False}
form=add('Company Leadership Form','n8n-nodes-base.formTrigger',{'formTitle':'Agent 4 — Public leadership background','formDescription':'Find publicly reported CEO, CISO, CTO and CIO, then research professional roles, Deloitte/KPMG/EY employment and SEC-school education. Four discovery searches plus up to four per distinct leader including public LinkedIn (maximum 20 initial searches). Public search snippets need original-source verification.','path':'agent4-leadership-background','formFields':{'values':[{'fieldLabel':'Company name','fieldName':'company_name','requiredField':True}]},'options':{}},[0,0],2.6);form['webhookId']=str(uuid.uuid4())
